Algorithm ExtractQuotient(states, d, C, contexts):
  Input: states [x_1,...,x_m], distance d, compression C, contexts
  Output: partition into equivalence classes

  Initialize Union-Find on {1,...,m}
  for i = 1 to m:
    for j = i+1 to m:
      if ObserverDistillation(d, C, contexts, x_i, x_j) = 0:
        Union(i, j)
  return partition induced by Union-Find

  Time: O(m^2 * n * T)
  Space: O(m)

Algorithm GenerateContexts(generators, max_depth):
  Input: generators [g_1,...,g_k], max depth d
  Output: all compositions up to depth d

  contexts <- {identity}
  current <- {identity}
  for depth = 1 to d:
    next <- empty
    for g in generators:
      for w in current:
        next <- next + {g . w}
    contexts <- contexts + next
    current <- next
  return contexts

  Output size: O(k^d)
